class Solution {
public:
    int houseCount(Street* street, int k) {
        for (int i = 0; i < k; ++i) {
            street->closeDoor();
            street->moveRight();
        }
        street->openDoor();
        street->moveRight();
        int count = 1;
        while (!street->isDoorOpen()) {
            ++count;
            street->moveRight();
        }
        return count;
    }
};
